local UIMainQuestNode = Class("UIMainQuestNode")
function UIMainQuestNode:__init()
    self._curType = 1
    self._data = {}
    self._coWarmUp = nil
    self._coFillSelf = nil
    self._hasBeenWarmUp = nil
end

function UIMainQuestNode:__delete()
    self._curType = nil
    self._data = nil
    self._coWarmUp = nil
    self._coFillSelf = nil
    self._hasBeenWarmUp = nil
end

function UIMainQuestNode:Awake()
    self._hasBeenWarmUp = false
    self:InitData()
    --SetButtonAction(self.BtnStory, Bind(self, self.OnBtnStory, false))
    --SetButtonAction(self.BtnChallenge, Bind(self, self.OnBtnChallenge, false))
end

function UIMainQuestNode:Start()
    self:WarmUp()
end

function UIMainQuestNode:WarmUp()
    if self._hasBeenWarmUp then return end
    if isNotNull(self._coWarmUp) then return end
    self._coWarmUp = cs_coroutine.start(function()
        -- print("[剧情节点] 预热")
        for i = 1, 3, 1 do
            self.BtnChapterList:ExpandPool()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.02))
        end
        self._hasBeenWarmUp = true
        self._coWarmUp = nil
    end)
end

function UIMainQuestNode:InitData(isChallenge)
    self._data = {}
    local t = isChallenge and CfUtils.GetCfTable(AutoIds.IdSetting6122) or CfUtils.GetCfTable(AutoIds.IdSetting281)

    if not t then
        return
    end
    local Vo = isChallenge and ChapterVoHardVo or ChapterVo
    for k, v in pairs(t) do
        local vo = Vo.New()
        vo:FillVo(v)
        vo.ind = checkNumber(k)
        table.insert(self._data, vo)
        print(vo.id)

        local isUnlock
        if isChallenge then
            isUnlock = QuestConfMgr:GetInstance():IsUnlockChallengeChapter(vo.id)
        else
            isUnlock = QuestConfMgr:GetInstance():IsUnlockChapter(vo.id)
        end
        if not isUnlock then
            return
        end
    end 
    if table.count(self._data) >= table.count(t) then
        table.insert(self._data, {
            id = -1,
            bigPic = "arts/instance/bigpic/main_bg_continued.png",
            pic = "arts/instance/Threadscene/main_bg_continued_s.png"
        })
    end
end

