function UIMainQuestNode:OnBtnStory(isEnforce)
    if self._isPlayAni then
        return
    elseif not isEnforce and checkNumber(self._curType) == Constants.IDType.QuestMain then
        return
    end

    self:InitData(false)
    self._curType = Constants.IDType.QuestMain
    self:SetMainQuestModelCache()
    self:FillModelInfo()

    --CfUtils.FillImage(self.ImgBg, "arts/textures/uibg/main_bg_story.png")
end

function UIMainQuestNode:OnBtnChallenge(isEnforce)
    if self._isPlayAni then
        return
    elseif not isEnforce and checkNumber(self._curType) == Constants.IDType.QuestMainChallenge then
        return
    end

    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id245)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id245))
        return    
    end

    self:InitData(true)
    self._curType = Constants.IDType.QuestMainChallenge
    self:SetMainQuestModelCache()
    self:FillModelInfo()
    ---@type QuestComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)

    local totalRewardTime = comp:GetChallengeTotalTimes()
    local havePassTime = comp:GetChallengePassedTimes()
    local leaveTime = totalRewardTime - havePassTime
    local color = leaveTime > 0 and "<color=#FFFFFF>%s</color>" or "<color=#ec2eae>%s</color>"
    CfUtils.FillText(self.TextNum,table.concat({string.format(color,leaveTime),"/",totalRewardTime}))

    --CfUtils.FillImage(self.ImgBg, "arts/textures/uibg/main_bg_challenge.png")
end

function UIMainQuestNode:SetMainQuestModelCache()
    KCookie.Set("MainQuestType", self._curType)
end

function UIMainQuestNode:FillModelInfo()
    KTool.SetActive(self.Story, checkNumber(self._curType) == Constants.IDType.QuestMain)
    KTool.SetActive(self.Challenge, not (checkNumber(self._curType) == Constants.IDType.QuestMain))
    CfUtils.SetUISwitchImage(self.ImgMobile, checkNumber(self._curType) == Constants.IDType.QuestMain and 1 or 2)

    self:FillSelf()

    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self._co = cs_coroutine.start(function()
        self._isPlayAni = true
        local aniName = (checkNumber(self._curType) == Constants.IDType.QuestMain) and "ToStory" or "ToChallenge"
        CfUtils.PlayAnimator(self.BgContainer, aniName)
        coroutine.yield(WaitForSeconds(0.34))
        self._isPlayAni = false
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainQuestNode")
    end)
end

function UIMainQuestNode:RefreshPos()
    local curChapterId, isPassAll = self:GetCurChapterId()
    local ind = CfUtils.GetTableValueKey(self._data, "id", checkNumber(curChapterId))
    self._curInd = ind
    if self._curInd then
        self.BtnChapterList:MovePanelToIndex(checkNumber(self._curInd) - 1)
    end
end

function UIMainQuestNode:FillSelf()
    if self._coFillSelf then
        cs_coroutine.stop(self._coFillSelf)
        self._coFillSelf = nil
    end
    self._coFillSelf = cs_coroutine.start(function()
        if not self._hasBeenWarmUp then
            self:WarmUp()
        end
        while not isNull(self._coWarmUp) do
            cs_coroutine.yield_return(nil)
        end
        -- print("[剧情节点] 填充")
        CfUtils.SetActive(self.BtnChapterList, false)
        self.BtnChapterList:InitListView(0, self._data)
        CfUtils.SetActive(self.BtnChapterList, true)
        self.BtnChapterList:InitListView(table.count(self._data), self._data)
        self.BtnChapterList.OnIndexChanged = Bind(self, self.OnSelectCell)

        --if not self._curInd then
            local curChapterId, isPassAll = self:GetCurChapterId()
            local ind = CfUtils.GetTableValueKey(self._data, "id", checkNumber(curChapterId))
        --end 
        --if checkNumber(self._curType) == Constants.IDType.QuestMain then
            if self._lastSelectId then
                local lastInd = CfUtils.GetTableValueKey(self._data, "id", checkNumber(self._lastSelectId))
                if checkNumber(lastInd) <= checkNumber(ind) and checkNumber(lastInd) > 0 then
                    ind = lastInd
                end
            end
        --end

        if checkNumber(KCookie.Get("MainQuestLastPassChapter")) > 0 then
            ind = CfUtils.GetTableValueKey(self._data, "id", checkNumber(KCookie.Get("MainQuestLastPassChapter")))
            KCookie.Set("MainQuestLastPassChapter", 0)
        end

        self._curInd = ind
        if self._curInd then
            self.BtnChapterList:MovePanelToIndex(checkNumber(self._curInd) - 1)
        end

        local data = self._data[self._curInd]
        self:FillCurChapterInfo(data)
        self._coFillSelf = nil
    end)
end

function UIMainQuestNode:GetCurChapterId()
    local curChapterId, isPassAll
    local key = "LastSelectChapterId"
    if checkNumber(self._curType) == Constants.IDType.QuestMain then
        curChapterId, isPassAll = QuestConfMgr:GetInstance():GetCurChapterId()
    else
        curChapterId, isPassAll = QuestConfMgr:GetInstance():GetCurChallengeChapterId()
        key = "LastSelectHardChapterId"
    end

    local lastSelectChapterId = checkNumber(KCookie.Get(key))
    if (lastSelectChapterId) > 0 then
        curChapterId = lastSelectChapterId
        KCookie.Set(key, 0)
    end

    return curChapterId, isPassAll
end

function UIMainQuestNode:OnSelectCell(index)
    local vo = self._data[index + 1]
    self:FillCurChapterInfo(vo)

    --if checkNumber(self._curType) == Constants.IDType.QuestMain then
        self._lastSelectId = vo.id
    --end
end 

function UIMainQuestNode:FillCurChapterInfo(data)
    if not data then
        return
    end
    if checkNumber(data.id) == -1 then
        KTool.SetActive(self.Content, false)
        return
    end
    KTool.SetActive(self.Content, true)

    --CfUtils.FillImage(self.ImgBg, data.namePic)
    local storyname = string.gsub(data.name, '\\n', '\n')
    CfUtils.FillText(self.StoryText, storyname)
    CfUtils.FillText(self.ChallengeText, storyname)
    CfUtils.FillText(self.Text1, data.title1)

    if isNotNull(data.title2) and not string.isEmpty(data.title2) then
        local title2 = string.gsub(data.title2, '\\n', '\n')
        CfUtils.FillText(self.Text2, title2)
    else
        CfUtils.FillText(self.Text2, "")
    end

    if checkNumber(self._curType) == Constants.IDType.QuestMain then
        if self._labelCo then
            cs_coroutine.stop(self._labelCo)
            self._labelCo = nil
        end
        self._labelCo = cs_coroutine.start(function()
            if self.Content.childCount > 2 then
                for i = self.Content.childCount - 1, 1, -1 do
                    local go = self.Content.transform:Find("go"..i)
                    if go then
                        CfUtils.PlayAnimator(go, "Out")
                        coroutine.yield(WaitForSeconds(0.015))
                        KTool.SetActive(go, false)
                    end
                end
            end

            local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2513, data.id)
            for i = 1, #t do
                local id = t[i]
                local data = self:GetMainChapterPageInfoVo(id)
                local go = self.Content.transform:Find("go"..i)
                if not go then
                    go = CfUtils.InstantiateGo(self.Cell, self.Content)
                    go.name = "go"..i
                end
                self:FillLabelInfo(go, data)
                CfUtils.PlayAnimator(go, "ShowIn")
                coroutine.yield(WaitForSeconds(0.015))
            end
            self._labelCo = nil
        end)
    end
end

function UIMainQuestNode:FillLabelInfo(go, data)
    if not go or not data then
        return
    end
    local path = ParseUtils.ParsePathNameByData(data.pic)
    local animRootGo = go.transform:Find("AnimRoot")
    CfUtils.FillText(animRootGo.transform:Find("Layout/TextTitle"), data.title)
    CfUtils.FillText(animRootGo.transform:Find("Layout/TextContent"), CfUtils.StrChange(data.text, 35))
    CfUtils.FillImage(animRootGo.transform:Find("ImgIcon1"), path)
    KTool.SetActive(go, true)
end

--章节装饰信息
function UIMainQuestNode:GetMainChapterPageInfoVo(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting2513, "MainChapterPageInfoVo", id)
    return vo
end

--获取当前下标 引导使用
function UIMainQuestNode:GetCurIndex()
    return self._curInd
end

function UIMainQuestNode:OnDestroy()
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    if self._labelCo then
        cs_coroutine.stop(self._labelCo)
        self._labelCo = nil
    end
    if self._coWarmUp then
        cs_coroutine.stop(self._coWarmUp)
        self._coWarmUp = nil
    end
    if self._coFillSelf then
        cs_coroutine.stop(self._coFillSelf)
        self._coFillSelf = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMainQuestNode